    public void ApplyColors(){var p=C.Colors;BackColor=GlassActive?Color.Black:p.Bg;foreach(Control b in Controls)b.Invalidate();if(refresh!=null){refresh.Enabled=!C.Refreshing;refresh.Text=C.Refreshing?"更新中":"刷新";}
