      Label("同步间隔",24,550,160,27);var interval=new GroveCombo{Colors=()=>C.Colors,Font=Art.Font(12*Scale),AccessibleName="同步间隔",Anchor=AnchorStyles.Top|AnchorStyles.Right};interval.Items.AddRange(new object[]{"5 分钟","10 分钟","30 分钟"});interval.SelectedIndex=C.Prefs.intervalSeconds==600?1:C.Prefs.intervalSeconds==1800?2:0;Place(interval,width-220,546,184,32);interval.SelectedIndexChanged+=(s,e)=>{C.Prefs.intervalSeconds=new[]{300,600,1800}[interval.SelectedIndex];C.SavePrefs();};settings.ContentControls.Add(interval);
